        data = response.json()
        assert isinstance(data.get("id"), int), "id should be an integer"
        assert isinstance(data.get("petId"), int), "petId should be an integer"
        assert isinstance(data.get("quantity"), int), "quantity should be an integer"
        assert "shipDate" in data, "shipDate should be present in response"
        assert isinstance(data.get("status"), str), "status should be a string"
